Method.Implementation:
$$$TRACE("inside the class ")
try {
 set jsonBodyData = pInput.Read(.len,.status)
 $$$TRACE(" JSON (PainScore Event Data) : "_jsonBodyData)
}
catch e
{
	 $$$TRACE(" Unknown Exception: " _ e)
	 set errTxt = $System.Status.GetErrorText("Unknown Exception "_e)		 
 	 Set tSC = ##class(IHC.ITF.ITFCOMMON.Utility).DisableMsgError(..%ConfigName,errTxt)	  
	 set tSC = $$$OK

}
